content:
{
 "kind": "sequence",
 "format": 1,
 "id": "seq_raptor_close",
 "name": "Raptor News: the outro",
 "set": "set_raptor_news",
 "roles": {
  "a": {
   "mark": "a",
   "label": "Anchor"
  },
  "b": {
   "mark": "b",
   "label": "Co-anchor"
  }
 },
 "wallText": "RAPTOR NEWS",
 "wallSub": "Trust no one but us",
 "beats": [
  {
   "id": "b1",
   "shot": {
    "cam": "cam1",
    "frame": "two",
    "on": [
     "a",
     "b"
    ],
    "move": "pull",
    "cut": "cut"
   },
   "say": {
    "role": "a",
    "lines": [
     "That's the news. It was bad, and it'll be bad tomorrow. I'm {a.name}.",
     "For all of us at Raptor News, I'm {a.name}. Stay indoors."
    ]
   },
   "gfx": []
  },
  {
   "id": "b2",
   "shot": {
    "cam": "cam3",
    "frame": "medium",
    "on": [
     "b"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "b",
    "lines": [
     "And I'm {b.name}. Good night, and lock your door.",
     "I'm {b.name}. Good night, Coldwater. Trust nobody."
    ]
   },
   "gfx": []
  },
  {
   "id": "b3",
   "shot": {
    "cam": "jib",
    "frame": "wide",
    "on": [],
    "move": "crane",
    "cut": "dissolve"
   },
   "hold": 3,
   "gfx": [
    {
     "kind": "full",
     "title": "RAPTOR NEWS",
     "sub": "Nightly Fury",
     "at": 0.6,
     "for": 0
    }
   ]
  }
 ]
}
